local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Players = game:GetService("Players")

local Player = Players.LocalPlayer
local Camera = workspace.CurrentCamera

-- Config (your requested "0, -1, -5 smth" style - slightly lower & farther)
local DEFAULT_Z_OFFSET = -5     -- deeper forward (negative Z = in front)
local DEFAULT_Y_OFFSET = -1     -- lower than chest level
local MIN_Z = -8
local MAX_Z = -2
local LERP_SPEED = 0.28         -- smooth but responsive

-- Variables
local Character, Humanoid, Torso, LeftArm, RightArm
local mainConnection
local currentZOffset = DEFAULT_Z_OFFSET
local targetZOffset = DEFAULT_Z_OFFSET

local function setupArms(char)
    Character = char
    Humanoid = char:WaitForChild("Humanoid", 8)
    Torso = char:WaitForChild("Torso", 8)  -- R6 only
    LeftArm = char:WaitForChild("Left Arm", 8)
    RightArm = char:WaitForChild("Right Arm", 8)
    
    if not (Torso and LeftArm and RightArm and Humanoid) then
        warn("Arm setup failed - retrying soon")
        task.delay(1, function() setupArms(char) end)
        return
    end
    
    -- FIX: Anchor BEFORE removing joints → no falling/deletion
    LeftArm.Anchored = true
    RightArm.Anchored = true
    
    -- Remove shoulders safely
    for _, name in {"Left Shoulder", "Right Shoulder"} do
        local joint = Torso:FindFirstChild(name)
        if joint then joint:Destroy() end
    end
    
    -- Physics safety
    LeftArm.CanCollide = false
    RightArm.CanCollide = false
    LeftArm.Massless = true
    RightArm.Massless = true
    
    -- CRITICAL: Client owns the arms → Roblox won't delete them
    pcall(function()
        LeftArm:SetNetworkOwner(Player)
        RightArm:SetNetworkOwner(Player)
    end)
    
    -- Reset offset
    currentZOffset = DEFAULT_Z_OFFSET
    targetZOffset = DEFAULT_Z_OFFSET
    
    print("✅ Both arms anchored, owned & ready!")
end

local function startFloating()
    if mainConnection then mainConnection:Disconnect() end
    
    mainConnection = RunService.Heartbeat:Connect(function()
        if not (LeftArm and LeftArm.Parent and RightArm and RightArm.Parent) then return end
        
        currentZOffset = currentZOffset + (targetZOffset - currentZOffset) * LERP_SPEED
        
        local baseCF = Camera.CFrame 
            * CFrame.new(0, DEFAULT_Y_OFFSET, currentZOffset)  -- 0 X, -1 Y, -5 Z base
        
        -- LEFT ARM
        LeftArm.CFrame = baseCF
            * CFrame.new(-1.8, 0, 0)
            * CFrame.Angles(math.rad(90), 0, math.rad(12))
        
        -- RIGHT ARM (mirrored)
        RightArm.CFrame = baseCF
            * CFrame.new(1.8, 0, 0)
            * CFrame.Angles(math.rad(90), 0, math.rad(-12))
    end)
end

-- Controls: Q = forward (closer), E = back (farther)
UserInputService.InputBegan:Connect(function(input, processed)
    if processed then return end
    
    local step = 1.3  -- adjust step size if too fast/slow
    
    if input.KeyCode == Enum.KeyCode.Q then
        targetZOffset = math.clamp(targetZOffset + step, MIN_Z, MAX_Z)
    elseif input.KeyCode == Enum.KeyCode.E then
        targetZOffset = math.clamp(targetZOffset - step, MIN_Z, MAX_Z)
    end
end)

-- Handle respawns/deaths (arms come back every time)
Player.CharacterAdded:Connect(function(char)
    task.wait(0.6)  -- wait for full R6 character load
    setupArms(char)
    startFloating()
end)

-- Initial setup
if Player.Character then
    task.wait(0.5)
    setupArms(Player.Character)
    startFloating()
end

print("Both arms floating @ ~0, -1, -5 base! Q = forward | E = back")
print("No more deletion - anchored + client-owned forever 🦾🦾")

